def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 90.0))
        return float(min(budget, 18.0))

    highest_prev = 0.0
    cindy_prev = None
    pressure_count = 0
    needy_opponents = 0

    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            needy_opponents += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            if bid > highest_prev:
                highest_prev = bid
            if bid >= 80:
                pressure_count += 1
        if opp.get('water_requirement') == 13 and opp.get('daily_salary') == 70:
            if bid is not None and bid >= 100:
                cindy_prev = bid

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    base = 22.0

    if cindy_prev is not None:
        if hp <= 2 or no_water_days >= 1:
            base = max(base, cindy_prev + 3.0)
        elif slots == 1:
            base = max(base, cindy_prev + 1.5)
        else:
            base = max(base, cindy_prev - 10.0)
    elif highest_prev > 0:
        if hp <= 2 or no_water_days >= 1:
            base = max(base, highest_prev + 2.0)
        else:
            base = max(base, highest_prev * 0.75)
    else:
        if hp <= 2 or no_water_days >= 1:
            base = 85.0
        else:
            base = 28.0

    if slots == 1:
        base += 10.0
    elif slots >= 2:
        base -= 6.0

    if needy_opponents >= 1:
        base += 6.0
    if pressure_count >= 2:
        base += 8.0

    if hp >= 8 and no_water_days == 0 and slots >= 2:
        base -= 8.0

    if day >= 8 and hp <= 4:
        base += 10.0

    reserve = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve = min(budget * 0.35, days_left * 18.0)

    max_affordable = budget - reserve
    if hp <= 2 or no_water_days >= 1:
        max_affordable = budget

    if max_affordable < 0:
        max_affordable = budget * 0.5

    bid = min(base, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    if hp <= 2 or no_water_days >= 1:
        emergency = 115.0
        if cindy_prev is not None:
            emergency = max(emergency, cindy_prev + 3.0)
        bid = min(budget, max(bid, emergency))

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    is_critical_hp = my_status['hp'] <= 3
    is_no_water_penalty = my_status['no_water_days'] >= 1
    is_end_game = day_context['day'] >= EPISODE_DAYS - 2

    base_bid = DAILY_SALARY * 0.55

    if is_critical_hp or is_no_water_penalty:
        base_bid = DAILY_SALARY * 0.9
    elif is_end_game:
        base_bid = DAILY_SALARY * 0.85

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = 0
    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)

    my_bid = base_bid
    if max_prev_bid > 0:
        if is_critical_hp or is_no_water_penalty:
            my_bid = max(my_bid, max_prev_bid + 5)
        else:
            my_bid = max(my_bid, max_prev_bid + 1)

    if day_context['supply'] < WATER_REQ * 1.5:
        if is_critical_hp or is_no_water_penalty:
            my_bid = max(my_bid, DAILY_SALARY * 0.98)
        else:
            my_bid = max(my_bid, DAILY_SALARY * 0.85)
    elif day_context['supply'] < WATER_REQ * 2:
        my_bid = max(my_bid, DAILY_SALARY * 0.75)

    final_bid = min(my_status['budget'], my_bid)
    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents, take what we can afford.
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from alive opponents only.
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Baseline bid from observed contest band.
    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
        max_prev = max(yesterday_bids)
    else:
        avg_prev = DAILY_SALARY * 0.55
        max_prev = DAILY_SALARY * 0.7

    # Estimate how many water units are likely contested.
    # Supply is total units; each unit requires WATER_REQ water to avoid no-water penalty.
    # We use a coarse mapping to decide aggressiveness.
    supply_units = supply / float(WATER_REQ)
    # More units => we can bid less; fewer units => bid more.
    if supply_units <= 2.0:
        scarcity_factor = 1.0
    elif supply_units <= 3.0:
        scarcity_factor = 0.85
    else:
        scarcity_factor = 0.7

    # If we are close to death or already have no-water days, overbid to secure.
    danger = (my_hp <= 2) or (my_no_water_days >= 2)

    # Target bid: slightly above the typical contest band to beat Alex/Cindy style bidding.
    if danger:
        # Push toward the top of yesterday's band.
        target = min(max_prev + 2.0, DAILY_SALARY * 0.95)
    else:
        # Healthy: bid just above average_prev, scaled by scarcity.
        target = (avg_prev + 3.0) * scarcity_factor
        # Keep within reasonable range.
        target = max(target, DAILY_SALARY * 0.45)
        target = min(target, DAILY_SALARY * 0.8)

    # Convert to feasible bid under our budget.
    bid = max(0.0, min(my_budget, float(target)))

    # Small final adjustment: if supply is high, reduce a touch to save budget.
    if supply >= 22.0 and not danger:
        bid = bid * 0.92

    return float(bid)

